import{_ as e,o as a,c as o,a3 as d}from"./chunks/framework.CVt6dz2a.js";const s="/threejs-tutorial-site/assets/EP.38-fsm-states.BF9Hb5CU.svg",q=JSON.parse('{"title":"EP.38 角色在想什么：输入映射与状态机","description":"","frontmatter":{},"headers":[],"relativePath":"comics/EP.38-fsm-states.md","filePath":"comics/EP.38-fsm-states.md","lastUpdated":1793881879000}'),r={name:"comics/EP.38-fsm-states.md"};function c(i,t,l,u,n,h){return a(),o("div",null,[...t[0]||(t[0]=[d('<h1 id="ep-38-角色在想什么-输入映射与状态机" tabindex="-1">EP.38 角色在想什么：输入映射与状态机 <a class="header-anchor" href="#ep-38-角色在想什么-输入映射与状态机" aria-label="Permalink to &quot;EP.38 角色在想什么：输入映射与状态机&quot;">​</a></h1><p><img src="'+s+'" alt="EP.38 状态机：像素酱、码叔与标签君把散落的布尔值收进一张合法转移表"></p><blockquote><p><strong>对应正文</strong>：<a href="./../guide/38-gameplay-systems/basics">38.1 基础入门：输入映射与状态机</a><strong>延伸阅读</strong>：<a href="./../guide/38-gameplay-systems/advanced">38.2 进阶应用：交互系统与任务设计</a> · <a href="./../guide/38-gameplay-systems/practice">38.3 实战案例：关卡系统、计分与存档</a><strong>动手演示</strong>：<a href="./../public/demos/gameplay/fsm-lab.html">fsm-lab 状态机调试台</a> · <a href="./../public/demos/gameplay/interaction-lab.html">interaction-lab 交互系统实验</a> · <a href="./../public/demos/gameplay/level-systems-lab.html">level-systems-lab 关卡系统实验</a></p></blockquote><h2 id="剧情回顾" tabindex="-1">剧情回顾 <a class="header-anchor" href="#剧情回顾" aria-label="Permalink to &quot;剧情回顾&quot;">​</a></h2><table tabindex="0"><thead><tr><th>格</th><th>画面</th><th>关键对白</th><th>梗 / 记忆点</th></tr></thead><tbody><tr><td>1</td><td>像素酱的角色跳在半空，攻击键却生效了；<code>isJumping</code> 与 <code>isAttacking</code> 同时亮起</td><td>&quot;我跳起来了，结果还能攻击？&quot; / &quot;日志里两个状态同时在跑。&quot;</td><td>状态散成一堆布尔值，非法组合防不胜防</td></tr><tr><td>2</td><td>码叔画出 KEY → ACTION → STATE 三层，按键先翻译成语义动作</td><td>&quot;先把按键翻译成语义动作，再让状态机决定能不能做。&quot;</td><td>输入映射层隔离设备，状态机只认事件</td></tr><tr><td>3</td><td>标签君把合法转移表摊在桌上：状态、事件、去向三列</td><td>&quot;这张表就是唯一事实来源。&quot;</td><td>查表失败就拒绝并记日志，非法转移无处可藏</td></tr><tr><td>4</td><td>码叔总结三条纪律，把&quot;布尔混用、转移散落、帧计时&quot;贴到墙上</td><td>&quot;状态收敛成一个变量，规则收敛到一张表。&quot;</td><td>同一入口、单一状态、dt 积分，是状态机三连</td></tr></tbody></table><h2 id="知识点拆解" tabindex="-1">知识点拆解 <a class="header-anchor" href="#知识点拆解" aria-label="Permalink to &quot;知识点拆解&quot;">​</a></h2><h3 id="_1-布尔值不是状态机" tabindex="-1">1. 布尔值不是状态机 <a class="header-anchor" href="#_1-布尔值不是状态机" aria-label="Permalink to &quot;1. 布尔值不是状态机&quot;">​</a></h3><p><code>isJumping</code>、<code>isAttacking</code>、<code>isHurt</code> 各自为真时，系统允许出现&quot;跳跃中攻击&quot;&quot;受伤中移动&quot;这类非法组合。有限状态机把&quot;正在做什么&quot;收敛成一个变量，任意时刻只有一个当前状态，非法组合从&quot;可能发生&quot;变成&quot;无法表示&quot;。这一格的笑点在于：角色不是不会动，而是没人说得清它现在在干什么。</p><h3 id="_2-输入映射是设备与规则之间的隔离带" tabindex="-1">2. 输入映射是设备与规则之间的隔离带 <a class="header-anchor" href="#_2-输入映射是设备与规则之间的隔离带" aria-label="Permalink to &quot;2. 输入映射是设备与规则之间的隔离带&quot;">​</a></h3><p><code>keyCode</code> 把物理按键、字符、输入法、手柄、触摸屏混在一起。正确顺序是设备事件 → 语义动作 → 状态机。设备层只负责&quot;哪个输入被按下&quot;，游戏层只认 <code>jump</code>、<code>attack</code>、<code>moveForward</code>。这样改键位、加手柄、加屏幕按钮，都不需要动状态机一行代码。</p><h3 id="_3-合法转移表是单一事实来源" tabindex="-1">3. 合法转移表是单一事实来源 <a class="header-anchor" href="#_3-合法转移表是单一事实来源" aria-label="Permalink to &quot;3. 合法转移表是单一事实来源&quot;">​</a></h3><p>把&quot;从哪个状态、收到哪个事件、去哪个状态&quot;写成数据，而不是散落在十几个 <code>if</code> 里。表驱动带来三个好处：非法输入有统一拒绝路径；转移日志可以完整还原时间线；状态机图可以直接从表生成。严格模式拒绝非法转移，宽容模式允许&quot;容错转移&quot;，都是同一张表的不同策略。</p><h3 id="_4-状态机的三条纪律" tabindex="-1">4. 状态机的三条纪律 <a class="header-anchor" href="#_4-状态机的三条纪律" aria-label="Permalink to &quot;4. 状态机的三条纪律&quot;">​</a></h3><p>第一，任何时刻只有一个当前状态；第二，所有转移都走同一个入口，包括落地、攻击结束、硬直结束这些系统事件；第三，所有计时都用 <code>dt</code> 累加，并在单帧做上限保护。做到这三条，角色才会&quot;想的&quot;和&quot;做的&quot;一致，调试日志也才有意义。</p><h2 id="坑点清单" tabindex="-1">坑点清单 <a class="header-anchor" href="#坑点清单" aria-label="Permalink to &quot;坑点清单&quot;">​</a></h2><ul><li><strong>坑点一：状态与布尔值混用。</strong> 一边维护 <code>state</code>，一边又维护 <code>isJumping</code>，两者迟早不同步，表现为&quot;状态显示 idle，角色还在空中&quot;。</li><li><strong>坑点二：自动转移绕过入口。</strong> 落地、攻击结束直接改 <code>state</code>，不走 <code>request(&#39;land&#39;)</code>，日志缺一半，回放对不上。</li><li><strong>坑点三：用帧数计时。</strong> 60Hz 与 144Hz 下动作时长差一倍多，必须用 <code>dt</code> 积分并 clamp 单帧上限。</li><li><strong>坑点四：长按直接执行动作。</strong> <code>keydown</code> 会重复触发，跳跃键按住会连跳；用 <code>event.repeat</code> 过滤，或把输入先写入意图集合再统一消费。</li></ul><h2 id="自测" tabindex="-1">自测 <a class="header-anchor" href="#自测" aria-label="Permalink to &quot;自测&quot;">​</a></h2><details><summary><b>Q1：为什么用 `event.code` 而不是 `event.key` 做固定键位映射？</b></summary><p><code>event.key</code> 表示按下的字符，受大小写、Shift、输入法和键盘布局影响；<code>event.code</code> 表示物理键位，<code>KeyW</code> 始终是那颗 W 键。游戏里做固定键位时用 <code>code</code> 更稳定；做&quot;玩家自定义按键&quot;时，把 <code>code</code> 存进配置再映射到语义动作。真正要避免的是越过映射层，在业务代码里直接判断键值。</p></details><details><summary><b>Q2：输入缓冲和土狼时间有什么区别？</b></summary><p>土狼时间宽恕&quot;离开平台边缘后的位置判断迟滞&quot;，属于地面检测层，窗口约 0.1~0.15 秒；输入缓冲宽恕&quot;动作收尾前的按键空档&quot;，属于输入与状态机层，窗口约 0.15~0.3 秒。缓冲先存一个待办动作，等当前状态回到可行动状态再补发，补发前仍要重新查合法转移表。</p></details><details><summary><b>Q3：状态机是不是过度设计？什么时候该用？</b></summary><p>3 个状态以内，布尔值更省事；一旦出现&quot;跳跃中不能攻击、攻击中不能移动、受伤中不能跳跃&quot;这类互相打断的规则，布尔组合会指数增长。判断标准不是状态数量，而是&quot;是否出现了需要互相排斥的规则&quot;。规则开始互相打断，就该上状态机。</p></details><hr><blockquote><p>下一篇正文见 <a href="./../guide/38-gameplay-systems/basics">38.1 基础入门：输入映射与状态机</a>。漫画仅作概念预热，代码与验收细节以正文为准。</p></blockquote>',22)])])}const p=e(r,[["render",c]]);export{q as __pageData,p as default};
